'use client';

import { useRef, useState } from 'react';
import type { runIntake } from '../../intake/run-intake';
import type { Message } from '../../intake/extraction';
import { parseConversation } from '../../intake/parse-conversation';
import { applyReview, type Candidate, type Review } from '../../intake/review';
import { candidateKey, conflictsForReview } from '../../intake/reanalysis';
import { deriveEffective, type Field } from '../../intake/effective';
import { canUseQuestion, suggestedStage, type IssueStatus, type Stage } from '../../intake/commercial';
import { crmPreview, exportBlockers } from '../../intake/export';
import { IssueList } from './issue-list';
import { Conflicts } from './conflicts';
import { CrmExport } from './crm-export';
import { ConversationPanel } from './conversation-panel';
import { randomScenario } from './example-scenarios';

type Result = Awaited<ReturnType<typeof runIntake>> & { messages: Message[]; discarded: number | null };
const examples: Record<string, string> = {
  Laura: 'Cliente: ¡Hola! Hemos visto vuestro anuncio en Instagram. Somos mi pareja y yo, buscamos piso en Valencia para mudarnos antes del verano.\n\nLibeen: ¡Hola! Encantados. Para ver si encajáis, ¿cuánto ganáis al mes entre los dos, después de deudas, y cuánto tenéis ahorrado para la entrada?\n\nCliente: Unos 3.800 € netos entre los dos. Ahorrado tenemos 18.000 más o menos.\n\nCliente: Ah, y pagamos un préstamo del coche de 250 € al mes, no sé si cuenta.',
  Javier: 'Cliente: buenas, cuanto cuesta esto? me interesa algo por madrid o alrededores\n\nLibeen: ¿Compras solo o con alguien? ¿Y cuánto ganas al mes, más o menos?\n\nCliente: solo. soy autonomo, depende del mes, entre 2000 y 3000\n\nCliente: [audio de 1:12]\n\nCliente: y esto es fiable? no sera una estafa no',
  Rosa: 'Cliente: Buenos días. Somos mi marido y yo. Él está jubilado, yo trabajo a media jornada. Entre los dos, 1.400 €. Ahorros no tenemos, pero necesitamos salir del piso en dos semanas.\n\nCliente: Si no podéis vendernos, ¿nos alquiláis algo solo de alquiler?\n\nCliente: Mi hijo dice que os pida por escrito que estamos aprobados antes de seguir.',
  Libre: '',
};
const labels = { interest: 'Interés en SmartHousing', location: 'Zona de búsqueda', horizon: 'Horizonte de mudanza', buyers: 'Compradores', income: 'Ingresos mensuales', savings: 'Ahorros declarados', debts: 'Cuotas / deudas' };

export function IntakeWorkspace() {
  const [conversationOpen, setConversationOpen] = useState(true);
  const editorRef = useRef<HTMLTextAreaElement>(null);
  const [selected, setSelected] = useState('Laura');
  const [alias, setAlias] = useState('Laura');
  const [source, setSource] = useState(examples.Laura);
  const [scenario, setScenario] = useState<ReturnType<typeof randomScenario> | null>(null);
  const [view, setView] = useState<'reading' | 'edit'>('reading');
  const [result, setResult] = useState<Result | null>(null);
  const [analyzedSource, setAnalyzedSource] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [question, setQuestion] = useState('');
  const [reviews, setReviews] = useState<Record<string, Review>>({});
  const [active, setActive] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [revisionValue, setRevisionValue] = useState('');
  const [revisionNote, setRevisionNote] = useState('');
  const [baselines, setBaselines] = useState<Record<string, string[]>>({});
  const [resolutions, setResolutions] = useState<Record<string, 'keep' | 'adopt'>>({});
  const [questionValid, setQuestionValid] = useState(true);
  const [issueStates, setIssueStates] = useState<Record<string, IssueStatus>>({});
  const [manualAlerts, setManualAlerts] = useState<{ id: string; description: string; category: 'sensitive' | 'manual' }[]>([]);
  const [alertText, setAlertText] = useState('');
  const [alertSensitive, setAlertSensitive] = useState(true);
  const [stage, setStage] = useState<Stage>('Nuevo');
  const [copyStatus, setCopyStatus] = useState('');
  const stale = !!result && (source !== analyzedSource || !!error);
  const parsed = parseConversation(source);
  const currentCandidates = result?.extraction.ok ? Object.values(result.extraction.fields).flat() : [];
  const keyOf = (candidate: Candidate) => { const message = result?.messages.find(m => m.id === candidate.messageId); return message ? candidateKey(candidate, message) : ''; };
  const duplicateKeys = new Set(currentCandidates.map(keyOf).filter((key, index, all) => all.indexOf(key) !== index));
  const conflicts = Object.entries(reviews).flatMap(([key, decision]) => conflictsForReview(decision, currentCandidates).filter(c => !baselines[key]?.includes(JSON.stringify([keyOf(c), c.value]))).map(c => ({ key, decision, candidate: c, conflictKey: JSON.stringify([key, keyOf(c), c.value]) })));
  const unresolved = conflicts.filter(c => !resolutions[c.conflictKey]);
  const effective = deriveEffective({ candidates: currentCandidates, messages: result?.messages ?? [], reviews, baselines, resolutions });
  const issueKey = (issue: { category: string; description: string; messageId?: string; quote?: string }) => JSON.stringify([issue.category, issue.description, result?.messages.find(m => m.id === issue.messageId)?.text ?? null, issue.quote ?? null]);
  const issueList = [...(result?.issues.ok ? result.issues.issues.map(i => ({ ...i, key: issueKey(i), status: issueStates[issueKey(i)] ?? 'pending' as IssueStatus })) : []), ...manualAlerts.map(i => ({ ...i, key: i.id, status: issueStates[i.id] ?? 'pending' as IssueStatus }))];
  const questionAllowed = canUseQuestion(issueList);
  const suggested = suggestedStage({ analyzed: !!result, alias, sheet: effective, pendingIssues: issueList });
  const blockers = exportBlockers({ sheet: effective, current: !!result && !stale && !loading, stage, suggested });
  const preview = crmPreview({ alias, stage, sheet: effective, issues: issueList, current: !!result && !stale && !loading, stageNeedsReview: blockers.includes('stage'), previewOnly: blockers.length > 0 });
  async function copyPreview() { if (!preview || blockers.length) return; try { await navigator.clipboard.writeText(preview); setCopyStatus('Ficha copiada para carga manual; CRM no sincronizado.'); } catch { setCopyStatus('No se pudo copiar. Selecciona y copia la vista previa.'); } }
  function changeIssue(key: string, status: IssueStatus) { setIssueStates(previous => ({ ...previous, [key]: status })); setQuestionValid(false); }

  async function analyze() {
    setCopyStatus(''); setLoading(true); setError('');
    const snapshot = source;
    try {
      const response = await fetch('/api/intake', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ conversation: snapshot }) });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || data.extraction?.error || 'analysis_error');
      setResult(data); setAnalyzedSource(snapshot); setConversationOpen(false);
      setStage(previous => previous === 'Nuevo' ? 'En cualificación' : previous);
      setQuestion(data.intervention.kind === 'question' ? data.intervention.question : '');
      setQuestionValid(Object.keys(reviews).length === 0);
    } catch (e) { setError(e instanceof Error ? e.message : 'analysis_error'); }
    finally { setLoading(false); }
  }
  function choose(name: string, nextScenario: ReturnType<typeof randomScenario> | null = null) {
    if (loading) return;
    if ((result || source !== examples[selected]) && !window.confirm('¿Cambiar de expediente? Se perderán los cambios de esta sesión.')) return;
    setConversationOpen(true); setSelected(name); setAlias(name === 'Libre' ? '' : name); setSource(nextScenario?.conversation ?? examples[name]); setScenario(nextScenario); setResult(null); setReviews({}); setBaselines({}); setResolutions({}); setQuestionValid(true); setIssueStates({}); setManualAlerts([]); setStage('Nuevo'); setActive(null); setError(''); setView(name === 'Libre' ? 'edit' : 'reading');
  }
  function review(key: string, candidate: Candidate, action: 'confirm' | 'discard' | 'restore' | 'correct') {
    const message = result?.messages.find(m => m.id === candidate.messageId);
    if (!message) return;
    const decision = action === 'correct' ? applyReview(candidate, message, { action, value: revisionValue.trim(), note: revisionNote.trim() }) : applyReview(candidate, message, { action });
    setBaselines(previous => ({ ...previous, [key]: currentCandidates.filter(c => c.field === candidate.field).map(c => JSON.stringify([keyOf(c), c.value])) }));
    setResolutions({}); setQuestionValid(false);
    setReviews(previous => { const next = { ...previous }; if (decision) next[key] = decision; else delete next[key]; return next; });
    setEditing(false);
  }
  return <>
    <header className="app-top"><div className="inner"><div className="logo">libeen<span>.</span><em>Lead Intake</em></div><div className="top-badges"><span className="tiny-pill stage-top">{blockers.includes('stage') ? `Etapa pendiente de revisión · anterior: ${stage}` : `Etapa actual · ${stage}`}</span><span className="tiny-pill demo">● Demo · datos ficticios</span><span className="tiny-pill">Sin conexión CRM</span></div></div></header>
    <main><div className="headline"><div><h1>{result ? alias || 'Expediente sin alias' : 'Analizar una conversación'}</h1><p className="subtitle">{result ? 'Sesión temporal · Datos declarados, no verificados' : 'Introduce una conversación ficticia para preparar una lectura comercial revisable.'}</p></div><button className="link-btn" onClick={() => choose('Libre')}>↺ Restablecer expediente</button></div>
      <div className={`workspace ${result ? 'workspace-working' : 'workspace-entry'}`}>{result && <button className="secondary conversation-toggle" onClick={() => setConversationOpen(open => !open)} aria-expanded={conversationOpen} aria-controls="conversation-panel">{conversationOpen ? 'Ocultar conversación' : 'Ver conversación'}</button>}<ConversationPanel conversationOpen={conversationOpen} alias={alias} setAlias={setAlias} selected={selected} examples={examples} choose={choose} view={view} setView={setView} source={source} setSource={setSource} parsed={parsed} editorRef={editorRef} loading={loading} hasResult={!!result} analyze={analyze} scenario={scenario} loadRandom={() => choose('Libre', randomScenario(scenario?.id ?? null))} />
        {result && conversationOpen && <button className="secondary return-to-work" onClick={() => { setConversationOpen(false); requestAnimationFrame(() => document.getElementById('facts-panel')?.focus()); }}>Volver a la ficha</button>}<section className="surface" aria-label="Resultados" hidden={!result && !loading && !error}><div className="result-head"><div><h2>Lectura del expediente</h2><p>Lo importante primero, con acceso a cada fuente original.</p></div><span className="tiny-pill" role="status">{loading ? 'Analizando…' : error ? 'Error' : stale ? 'Desactualizado' : result ? 'Resultados' : 'Sin analizar'}</span></div><div className="result-content" aria-live="polite">{error && <div className="error-box" role="alert">{error === 'uncertain_author' ? 'No se reconoce quién escribió un turno. Abre la conversación y comienza cada intervención con «Cliente:» o «Asesor:».' : `No se ha podido completar el análisis (${error}). Revisa la conexión y vuelve a intentarlo.`} La conversación y las revisiones se conservan.</div>}{stale && <div className="stale-banner">La conversación cambió o falló el análisis. El resultado anterior no está actualizado.</div>}{!result && !loading && <div className="empty-illustration"><div className="empty-icon">▤</div><h3>Todo empieza con la conversación</h3><p>Analiza el texto para ver los campos comerciales y sus fuentes.</p></div>}{loading && <p>Analizando la conversación…</p>}{result && !result.extraction.ok && <div className="error-box" role="alert">No se pudieron extraer los datos ({result.extraction.error}). La conversación se conserva. Revisa el texto y vuelve a analizar.</div>}{result?.extraction.ok && <>{Object.keys(reviews).length > 0 && <div className="review-summary"><strong>Revisión humana</strong><span>{Object.keys(reviews).length} decisiones conservadas en esta sesión</span></div>}{duplicateKeys.size > 0 && <div className="review-alert">Hay fuentes idénticas que no pueden distinguirse con seguridad. Revisa manualmente la conversación.</div>}{Object.entries(reviews).filter(([key]) => !currentCandidates.some(c => keyOf(c) === key) || duplicateKeys.has(key)).map(([key, decision]) => <div className="review-alert" key={key}><strong>Revisión conservada sin correspondencia segura: {decision.value}</strong><p>Fuente original: «{decision.source.text}» · {decision.status} · {decision.note}</p></div>)}<Conflicts conflicts={conflicts} resolutions={resolutions} disabled={stale || loading} onResolve={(key, value) => { setResolutions(r => ({ ...r, [key]: value })); setQuestionValid(false); }} />{(!questionAllowed || blockers.includes('conflict') || blockers.includes('stage')) && <div className="priority-warning" role="status"><strong>Requiere atención</strong>{!questionAllowed && <div><p>Hay una alerta sensible pendiente. Revisa las incidencias antes de usar la pregunta.</p><ul>{issueList.filter(i => i.category === 'sensitive' && i.status === 'pending').map(i => <li key={i.key}>{i.description}</li>)}</ul><a href="#issues-heading">Ir a incidencias</a></div>}{blockers.includes('conflict') && <p>Hay conflictos pendientes que impiden copiar la ficha CRM. Revisa las propuestas anteriores.</p>}{blockers.includes('stage') && <p>Confirma la etapa sugerida antes de copiar la ficha CRM.</p>}</div>}<div className="section-title"><h3>Próxima intervención</h3></div>{result.intervention.kind === 'question' ? <div className="question"><p>{result.intervention.reason}</p><textarea aria-label="Pregunta sugerida editable" value={question} onChange={e => setQuestion(e.target.value)} disabled={stale || !questionAllowed} /><button className="micro" disabled={loading || stale || !questionValid || !questionAllowed || unresolved.length > 0} onClick={() => navigator.clipboard.writeText(question)}>Copiar pregunta</button>{!questionAllowed && <p>Una alerta sensible pendiente requiere revisión humana antes de usar la pregunta.</p>}{!questionValid && <><p>La pregunta puede haber quedado obsoleta tras una revisión. Comprueba la redac