  const [reviews, setReviews] = useState<Record<string, Review>>({});
  const [active, setActive] = useState<string | null>(null);
  const [editing, setEditing] = useState(false);
  const [revisionValue, setRevisionValue] = useState('');
  const [revisionNote, setRevisionNote] = useState('');
  const [baselines, setBaselines] = useState<Record<string, string[]>>({});
  const [resolutions, setResolutions] = useState<Record<string, 'keep' | 'adopt'>>({});
  const [questionValid, setQuestionValid] = useState(true);
  const [issueStates, setIssueStates] = useState<Record<string, IssueStatus>>({});
  const [manualAlerts, setManualAlerts] = useState<{ id: string; description: string; category: 'sensitive' | 'manual' }[]>([]);
  const [alertText, setAlertText] = useState('');
