    vi.stubGlobal('fetch', vi.fn().mockResolvedValueOnce({ ok: true, json: async () => first }).mockResolvedValueOnce({ ok: true, json: async () => second }));
    await act(async () => { renderer = create(<IntakeWorkspace />); });
